1	package vault
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14	)
15	
16	// Snapshot is an immutable record of every name mapping in the repository at
17	// creation time. It only references existing content objects; no artifact
18	// bytes are copied.
19	type Snapshot struct {
20		Name    string           `json:"name"`
21		Entries map[string]Entry `json:"entries"`
22	}
23	
24	// SnapshotInfo summarizes a saved snapshot for listing.
25	type SnapshotInfo struct {
26		Name  string
27		Count int
28	}
29	
30	// CreateSnapshot records the current name mapping under the given snapshot
31	// name. The snapshot is written to a temporary file and renamed into place,
32	// so a crash leaves either the complete snapshot or none at all.
33	func (s *Store) CreateSnapshot(name string) (Snapshot, error) {
34		if err := validateName(name); err != nil {
35			return Snapshot{}, err
36		}
37		var snap Snapshot
38		err := s.withLock(true, func() error {
39			if err := s.initLocked(); err != nil {
40				return err
41			}
42			idx, err := s.load()
43			if err != nil {
44				return fmt.Errorf("cannot snapshot: current index is unreadable: %w", err)
45			}
46			path := s.snapshotPath(name)
47			if _, err := os.Stat(path); err == nil {
48				return fmt.Errorf("snapshot %q already exists", name)
49			} else if !errors.Is(err, os.ErrNotExist) {
50				return err
51			}
52			snap = Snapshot{Name: name, Entries: idx.Entries}
53			return s.saveSnapshot(path, snap)
54		})
55		if err != nil {
56			return Snapshot{}, err
57		}
58		return snap, nil
59	}
60	
61	// ListSnapshots returns every saved snapshot, sorted by its complete snapshot
62	// name, with the number of artifact records in its entries mapping.
63	//
64	// A snapshot is listed only after its record proves complete and legal: it is
65	// validated exactly the way RestoreSnapshot validates the record it restores
66	// (see decodeSnapshotRecord) — a single JSON object whose recorded name
67	// equals its filing name in full ("releases/stable", never just "stable"),
68	// with a present, object-valued entries mapping ({} is a legitimate empty
69	// snapshot; a missing or null entries field is corruption) containing only
70	// valid artifact records. The content objects the entries reference are not
71	// read or checked; listing depends on neither the objects nor the health of
72	// the current name mapping.
73	//
74	// One damaged, unreadable, or misplaced record fails the whole operation:
75	// the error names the complete snapshot and what is wrong with it and no
76	// SnapshotInfo is returned, so callers never see a partial list or read a
77	// name or count off a corrupt record. A repository whose snapshots directory
78	// does not exist yet simply has no snapshots and yields an empty list; a
79	// record read failing with "not exist" once the directory walk has started
80	// is reported rather than treated as absence. Non-snapshot files (temporary
81	// files and anything not ending in .json) are ignored. Listing never
82	// modifies the current mapping, any snapshot record, or any content object.
83	func (s *Store) ListSnapshots() ([]SnapshotInfo, error) {
84		infos := []SnapshotInfo{}
85		err := s.withLock(false, func() error {
86			return s.walkSnapshotRecords(func(name string, snap Snapshot) error {
87				infos = append(infos, SnapshotInfo{Name: name, Count: len(snap.Entries)})
88				return nil
89			})
90		})
91		if err != nil {
92			return nil, err
93		}
94		sort.Slice(infos, func(i, j int) bool { return infos[i].Name < infos[j].Name })
95		return infos, nil
96	}
97	
98	// walkSnapshotRecords enumerates the snapshot records filed under snapshots/
99	// and invokes fn with each record's complete snapshot name and its parsed,
100	// fully validated contents (see decodeSnapshotRecord). It is the single
101	// enumeration used by read-only operations that must see exactly the records
102	// restore would accept — listing and reference collection alike.
103	//
104	// A missing snapshots directory means no snapshots exist and is not an error.
105	// Every other problem aborts the walk: a symlinked or non-directory snapshots
106	// path, a symlink or other non-regular file beneath it, a .json file whose
107	// location does not encode a legal snapshot name, a record that cannot be
108	// read (including one that disappears mid-walk), and any malformed or
109	// incomplete record. Errors name the complete snapshot when its location is
110	// known. Files without a .json suffix (temporary files and other stray data)
111	// are skipped.
112	func (s *Store) walkSnapshotRecords(fn func(name string, snap Snapshot) error) error {
113		dir := s.snapshotsDir()
114		info, err := os.Lstat(dir)
115		switch {
116		case errors.Is(err, os.ErrNotExist):
117			return nil
118		case err != nil:
119			return fmt.Errorf("cannot inspect snapshots directory: %w", err)
120		case info.Mode()&os.ModeSymlink != 0:
121			return fmt.Errorf("snapshots path %q is a symbolic link", dir)
122		case !info.IsDir():
123			return fmt.Errorf("snapshots path %q is not a directory", dir)
124		}
125		return filepath.WalkDir(dir, func(path string, d fs.DirEntry, walkErr error) error {
126			if walkErr != nil {
127				// The directory entry was seen but the path can no longer be
128				// accessed: a vanished record is a read failure, not an empty set.
129				return walkErr
130			}
131			if d.IsDir() {
132				return nil
133			}
134			rel, err := filepath.Rel(dir, path)
135			if err != nil {
136				return err
137			}
138			isRecord := strings.HasSuffix(d.Name(), ".json")
139			// Name the snapshot when the offending path occupies a record slot;
140			// other stray entries are identified by path.
141			if d.Type()&os.ModeSymlink != 0 {
142				if isRecord {
143					name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
144					return fmt.Errorf("snapshot %q is a symbolic link", name)
145				}
146				return fmt.Errorf("snapshots contain symbolic link %q", path)
147			}
148			if !d.Type().IsRegular() {
149				if isRecord {
150					name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
151					return fmt.Errorf("snapshot %q is not a regular file", name)
152				}
153				return fmt.Errorf("snapshots contain non-regular file %q", path)
154			}
155			if !isRecord {
156				return nil
157			}
158			name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
159			if err := validateName(name); err != nil {
160				return fmt.Errorf("snapshot record %q does not map to a valid snapshot name: %w", path, err)
161			}
162			data, err := os.ReadFile(path)
163			if err != nil {
164				return fmt.Errorf("snapshot %q cannot be read: %w", name, err)
165			}
166			snap, err := decodeSnapshotRecord(data, name)
167			if err != nil {
168				return fmt.Errorf("snapshot %q is corrupted: %w", name, err)
169			}
170			return fn(name, snap)
171		})
172	}
173	
174	// RestoreSnapshot replaces the current name mapping with the snapshot's
175	// recorded mapping in a single atomic index write. The current index is never
176	// read, so restore works even when it is corrupted. The selected snapshot
177	// record must be a complete, well-formed document whose recorded name equals
178	// the selected snapshot name in full (a record nested under "releases/stable"
179	// must itself say "releases/stable", never just "stable") and whose entries
180	// mapping is present and an object ({} is a legitimate empty snapshot; a
181	// missing, null, or non-object entries field is corruption, never an empty
182	// mapping). Every referenced object is checked for existence, size, and
183	// SHA-256 before the mapping is swapped; any failure leaves the current
184	// mapping's bytes and all snapshots and objects untouched, even when the
185	// current mapping itself is already corrupted.
186	func (s *Store) RestoreSnapshot(name string) error {
187		if err := validateName(name); err != nil {
188			return err
189		}
190		return s.withLock(true, func() error {
191			if err := s.initLocked(); err != nil {
192				return err
193			}
194			snap, err := s.loadSnapshotRecord(name)
195			if err != nil {
196				return err
197			}
198			for _, entry := range snap.Entries {
199				if err := s.verifyObject(entry); err != nil {
200					return fmt.Errorf("cannot restore snapshot %q: object for %q: %w", name, entry.Name, err)
201				}
202			}
203			return s.save(index{Entries: snap.Entries})
204		})
205	}
206	
207	// decodeSnapshotRecord parses one snapshot record without touching the
208	// repository. wantName is the full snapshot name the record is selected or
209	// filed under and must record verbatim.
210	//
211	// A valid record is exactly one JSON object — never the bare null — with no
212	// duplicate or unknown fields and no trailing data, carrying:
213	//
214	//   - "name": present and a string equal to wantName, including every level of
215	//     a multi-level name; a missing, wrong-type, or merely-suffixed name
216	//     (record "stable" under "releases/stable") is refused;
217	//   - "entries": present and a JSON object. {} is a legitimate empty mapping;
218	//     a missing field, a null, an array, or any non-object value is
219	//     corruption rather than zero entries.
220	//
221	// Every entry is then checked with validateEntryRecord. The errors
222	// distinguish a missing entries mapping, a mismatching recorded name, and a
223	// malformed document so callers can tell record corruption apart from a
224	// snapshot that simply does not exist (that distinction is made by the
225	// caller, which checks the file before reading it).
226	func decodeSnapshotRecord(data []byte, wantName string) (Snapshot, error) {
227		if err := rejectDuplicateKeys(data); err != nil {
228			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
229		}
230		// The document must be a JSON object: a bare null, array, or primitive is
231		// a malformed record, never an empty snapshot.
232		if trimmed := bytes.TrimSpace(data); len(trimmed) == 0 || trimmed[0] != '{' {
233			return Snapshot{}, errors.New("malformed record: expected a JSON object with name and entries")
234		}
235		var raw struct {
236			Name    *string          `json:"name"`
237			Entries *json.RawMessage `json:"entries"`
238		}
239		dec := json.NewDecoder(bytes.NewReader(data))
240		dec.DisallowUnknownFields()
241		if err := dec.Decode(&raw); err != nil {
242			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
243		}
244		if tok, err := dec.Token(); err != io.EOF {
245			if err == nil {
246				return Snapshot{}, fmt.Errorf("malformed record: unexpected trailing content after the snapshot object (%v)", tok)
247			}
248			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
249		}
250		if raw.Name == nil {
251			return Snapshot{}, errors.New("malformed record: missing snapshot name")
252		}
253		if *raw.Name != wantName {
254			return Snapshot{}, fmt.Errorf("recorded name %q does not match snapshot %q", *raw.Name, wantName)
255		}
256		if raw.Entries == nil {
257			return Snapshot{}, errors.New("record is missing its entries mapping")
258		}
259		entriesJSON := *raw.Entries
260		if string(bytes.TrimSpace(entriesJSON)) == "null" {
261			return Snapshot{}, errors.New("record is missing its entries mapping")
262		}
263		var entries map[string]Entry
264		if err := json.Unmarshal(entriesJSON, &entries); err != nil {
265			return Snapshot{}, fmt.Errorf("entries mapping is malformed: %w", err)
266		}
267		if entries == nil {
268			return Snapshot{}, errors.New("record is missing its entries mapping")
269		}
270		for key, entry := range entries {
271			if err := validateEntryRecord(key, entry); err != nil {
272				return Snapshot{}, err
273			}
274		}
275		return Snapshot{Name: *raw.Name, Entries: entries}, nil
276	}
277	
278	func (s *Store) saveSnapshot(path string, snap Snapshot) error {
279		data, err := json.MarshalIndent(snap, "", "  ")
280		if err != nil {
281			return err
282		}
283		data = append(data, '\n')
284		if err := s.ensureSnapshotParent(path); err != nil {
285			return err
286		}
287		dir := filepath.Dir(path)
288		tmp, err := os.CreateTemp(dir, ".snapshot-*")
289		if err != nil {
290			return err
291		}
292		tmpName := tmp.Name()
293		defer os.Remove(tmpName)
294		if _, err := tmp.Write(data); err != nil {
295			tmp.Close()
296			return err
297		}
298		if err := tmp.Close(); err != nil {
299			return err
300		}
301		return os.Rename(tmpName, path)
302	}
303	
304	// ensureSnapshotParent creates the parent directories of a snapshot record one
305	// component at a time, refusing to follow symbolic links. Without this a nested
306	// snapshot name such as "evil/x" could be redirected through a pre-created
307	// snapshots/evil symlink to write outside the repository.
308	func (s *Store) ensureSnapshotParent(path string) error {
309		base := s.snapshotsDir()
310		rel, err := filepath.Rel(base, filepath.Dir(path))
311		if err != nil {
312			return err
313		}
314		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
315			return errors.New("snapshot path escapes the snapshots directory")
316		}
317		// The base directory itself must exist and be a real directory, even for a
318		// top-level snapshot (a freshly initialized repository has no snapshots/).
319		cur := base
320		if err := ensureRealDir(cur); err != nil {
321			return err
322		}
323		if rel == "." {
324			return nil
325		}
326		for _, component := range strings.Split(rel, string(filepath.Separator)) {
327			next := filepath.Join(cur, component)
328			if err := ensureRealDir(next); err != nil {
329				return err
330			}
331			cur = next
332		}
333		return nil
334	}
335	
336	// ensureRealDir makes sure path is a real directory, creating it if absent,
337	// and refuses an existing symlink or non-directory.
338	func ensureRealDir(path string) error {
339		info, err := os.Lstat(path)
340		switch {
341		case errors.Is(err, os.ErrNotExist):
342			if err := os.Mkdir(path, 0o755); err != nil && !errors.Is(err, os.ErrExist) {
343				return err
344			}
345			info, err = os.Lstat(path)
346			if err != nil {
347				return err
348			}
349		case err != nil:
350			return err
351		}
352		if info.Mode()&os.ModeSymlink != 0 {
353			return fmt.Errorf("repository path %q is a symbolic link", path)
354		}
355		if !info.IsDir() {
356			return fmt.Errorf("repository path %q is not a directory", path)
357		}
358		return nil
359	}
360	
361	func (s *Store) snapshotsDir() string { return filepath.Join(s.root, "snapshots") }
362	
363	func (s *Store) snapshotPath(name string) string {
364		return filepath.Join(s.snapshotsDir(), filepath.FromSlash(name)+".json")
365	}
366	
367	func isDigest(digest string) bool {
368		if len(digest) != 64 {
369			return false
370		}
371		for _, c := range digest {
372			if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
373				return false
374			}
375		}
376		return true
377	}
