31	func New(root string) *Store { return &Store{root: root} }
32	
33	// withLock serializes access to the repository across cooperating processes.
34	// Mutating operations pass exclusive=true; readers take a shared lock. The
35	// lock is an flock on <root>/.lock, so it is released automatically if a
36	// process dies mid-operation and nothing can wait forever on a stale lock.
37	func (s *Store) withLock(exclusive bool, fn func() error) error {
38		return s.withLockOpts(exclusive, true, fn)
39	}
40	
41	// withLockOpts is withLock with control over root creation. Read-only-style
42	// operations that must never materialize a missing repository (such as
43	// export) pass createRoot=false.
44	func (s *Store) withLockOpts(exclusive, createRoot bool, fn func() error) error {
45		if strings.TrimSpace(s.root) == "" {
46			return errors.New("root is required")
47		}
48		if createRoot {
49			if err := os.MkdirAll(s.root, 0o755); err != nil {
50				return err
51			}
52		}
53		// Read-only operations that must not materialize anything open the lock
54		// without O_CREATE: an initialized repository always has a lock file, so
55		// a missing one means the repository was never initialized.
56		var lock *os.File
57		var err error
58		if createRoot {
59			lock, err = os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o644)
60		} else {
61			lock, err = os.OpenFile(s.lockPath(), os.O_RDWR, 0o644)
62		}
63		if err != nil {
64			if !createRoot && errors.Is(err, os.ErrNotExist) {
65				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
66			}
67			return err
68		}
69		defer lock.Close()
70		mode := syscall.LOCK_SH
71		if exclusive {
72			mode = syscall.LOCK_EX
73		}
74		if err := syscall.Flock(int(lock.Fd()), mode); err != nil {
75			return err
76		}
77		defer syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
78		return fn()
79	}
80	
81	func (s *Store) Init() error {
82		return s.withLock(true, s.initLocked)
83	}
84	
85	func (s *Store) initLocked() error {
86		if err := os.MkdirAll(filepath.Join(s.root, "objects"), 0o755); err != nil {
87			return err
88		}
89		_, err := os.Stat(s.indexPath())
90		if errors.Is(err, os.ErrNotExist) {
91			return s.save(index{Entries: map[string]Entry{}})
92		}
93		return err
94	}
95	
96	// Put stores the content of source under name. The content is staged in a
97	// temporary file inside the repository while its size and SHA-256 are
98	// computed, then either installed as a new content object or matched against
99	// the object already stored under the same digest. A successful put means the
100	// object behind name's digest is verifiably complete: an existing object is
101	// reused only when it is a regular file whose full contents can be read and
102	// whose actual size and SHA-256 equal this upload's. Anything else — a
103	// truncated or rewritten object, a same-size object with different bytes, a
104	// symlink (followed or dangling), a directory, or an unreadable path — fails
105	// the upload and leaves the name mapping, the existing object, and every
106	// snapshot untouched; a damaged object is never repaired by overwriting it.
107	// Reuse never copies, rewrites, or re-permissions the healthy object, so
108	// several names can share one object.
109	func (s *Store) Put(name, source string) (Entry, error) {
110		if err := validateName(name); err != nil {
111			return Entry{}, err
112		}
113		if source == "" {
114			return Entry{}, errors.New("file is required")
115		}
116		var entry Entry
117		err := s.withLock(true, func() error {
118			if err := s.initLocked(); err != nil {
119				return err
120			}
121			in, err := os.Open(source)
122			if err != nil {
123				return err
124			}
125			defer in.Close()
126			tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".upload-*")
127			if err != nil {
128				return err
129			}
130			tmpName := tmp.Name()
131			defer os.Remove(tmpName)
132			hash := sha256.New()
133			size, copyErr := io.Copy(io.MultiWriter(tmp, hash), in)
134			closeErr := tmp.Close()
135			if copyErr != nil {
136				return copyErr
137			}
138			if closeErr != nil {
139				return closeErr
140			}
141			digest := hex.EncodeToString(hash.Sum(nil))
142			if err := s.placeObject(name, digest, size, tmpName); err != nil {
143				return err
144			}
145			idx, err := s.load()
146			if err != nil {
147				return err
148			}
149			entry = Entry{Name: name, Digest: digest, Size: size, CreatedAt: time.Now().UTC()}
150			idx.Entries[name] = entry
151			return s.save(idx)
152		})
153		if err != nil {
154			return Entry{}, err
155		}
156		return entry, nil
157	}
158	
159	// placeObject makes the content object for digest available in the
160	// repository. When no object exists at the digest path yet, the staged upload
161	// at tmpName is renamed into place. When something already exists there it is
162	// reused only if it proves to be a complete, intact copy of this upload (see
163	// checkReusableObject); otherwise the upload fails and the staged file is
164	// removed by the caller's deferred cleanup. An inspection failure is never
165	// treated as "object missing": only a genuine not-exist installs new content.
166	func (s *Store) placeObject(name, digest string, size int64, tmpName string) error {
167		object := s.objectPath(digest)
168		info, err := os.Lstat(object)
169		switch {
170		case errors.Is(err, os.ErrNotExist):
171			return os.Rename(tmpName, object)
172		case err != nil:
173			return fmt.Errorf("cannot store %q: cannot inspect existing object %s: %w", name, digest, err)
174		}
175		if err := checkReusableObject(info, object, digest, size); err != nil {
176			return fmt.Errorf("cannot store %q: %w", name, err)
177		}
178		return nil
179	}
180	
181	// checkReusableObject verifies that an existing content object is a complete,
182	// intact copy of the uploaded content: a regular file — never a symlink,
183	// whether or not its target exists, and never a directory or other special
184	// file — whose actual size and SHA-256 match the digest and size computed for
185	// this upload. The object is read in full; a read failure is reported, not
186	// treated as absence.
187	func checkReusableObject(info os.FileInfo, object, digest string, size int64) error {
188		if info.Mode()&os.ModeSymlink != 0 {
189			return fmt.Errorf("existing object %s is a symbolic link", digest)
190		}
191		if !info.Mode().IsRegular() {
192			return fmt.Errorf("existing object %s is not a regular file", digest)
193		}
194		file, err := os.Open(object)
195		if err != nil {
196			return fmt.Errorf("cannot read existing object %s: %w", digest, err)
197		}
198		hash := sha256.New()
199		n, copyErr := io.Copy(hash, file)
200		closeErr := file.Close()
201		if copyErr != nil {
202			return fmt.Errorf("cannot read existing object %s: %w", digest, copyErr)
203		}
204		if closeErr != nil {
205			return fmt.Errorf("cannot read existing object %s: %w", digest, closeErr)
206		}
207		if n != size {
208			return fmt.Errorf("existing object %s is corrupted: content is %d bytes, upload is %d", digest, n, size)
209		}
210		if actual := hex.EncodeToString(hash.Sum(nil)); actual != digest {
211			return fmt.Errorf("existing object %s is corrupted: content checksum is %s", digest, actual)
212		}
213		return nil
214	}
215	
216	func (s *Store) List() ([]Entry, error) {
217		var entries []Entry
218		err := s.withLock(false, func() error {
219			idx, err := s.load()
220			if err != nil {
221				return err
222			}
223			entries = make([]Entry, 0, len(idx.Entries))
224			for _, entry := range idx.Entries {
225				entries = append(entries, entry)
226			}
227			return nil
228		})
229		if err != nil {
230			return nil, err
231		}
232		sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
233		return entries, nil
234	}
235	
236	// Verify checks every entry of the current name mapping against its content
237	// object: the object must exist and its actual size and SHA-256 must match
238	// the recorded metadata. The mapping itself must be complete and unambiguous
239	// first: the index must be one complete JSON object with an explicitly
240	// present entries mapping (a true {"entries":{}} is a legitimate empty
241	// repository; null, a missing or null entries field, an array, truncated
242	// input, trailing content, or any duplicate key — including a name repeated
243	// through Unicode escapes — is corruption), and every record must pass the
244	// same validity checks downloads and gc apply (keyed by its recorded name, a
245	// legal name, a 64-character lowercase-hex digest, a non-negative size). A
246	// single malformed record fails the whole pass; bad records are never
247	// skipped to report success over the rest. Mapping problems are reported
248	// before any object is read, so index corruption is always distinguished
249	// from object damage.
250	//
251	// The whole pass — reading the mapping and checking every object it
252	// references — runs under one shared repository lock, so the mapping and the
253	// objects it points at cannot be replaced or collected by another process
254	// between the first read and the last check: an overwrite, snapshot restore,
255	// import, or gc either completes before the pass starts (and the pass
256	// observes the completed state) or waits until the pass ends. The lock is
257	// shared, so concurrent lists, downloads, and other verifies proceed
258	// alongside it. Verify never rewrites the mapping, snapshots, or objects,
259	// and never repairs damaged content; on the first failure it reports the
260	// cause and returns a zero count.
261	func (s *Store) Verify() (int, error) {
262		count := 0
263		err := s.withLock(false, func() error {
264			idx, err := s.loadStrict()
265			if err != nil {
266				return err
267			}
268			entries := make([]Entry, 0, len(idx.Entries))
269			for key, entry := range idx.Entries {
270				if err := validateEntryRecord(key, entry); err != nil {
271					return fmt.Errorf("current index is corrupt: %w", err)
272				}
273				entries = append(entries, entry)
274			}
275			// Sort by name so the first reported failure is deterministic.
276			sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
277			for _, entry := range entries {
278				if err := s.verifyObject(entry); err != nil {
279					return fmt.Errorf("verify %q: %w", entry.Name, err)
280				}
281			}
282			count = len(entries)
283			return nil
284		})
285		if err != nil {
286			return 0, err
287		}
288		return count, nil
289	}
290	
291	// verifyObject checks that the content object for entry exists and that its
292	// actual size and SHA-256 match the recorded metadata.
293	func (s *Store) verifyObject(entry Entry) error {
294		file, err := os.Open(s.objectPath(entry.Digest))
295		if err != nil {
296			return err
297		}
298		hash := sha256.New()
299		size, copyErr := io.Copy(hash, file)
300		closeErr := file.Close()
301		if copyErr != nil || closeErr != nil {
302			return errors.New("read failed")
303		}
304		if size != entry.Size || hex.EncodeToString(hash.Sum(nil)) != entry.Digest {
305			return errors.New("content mismatch")
306		}
307		return nil
308	}
309	
310	func (s *Store) load() (index, error) {
311		data, err := os.ReadFile(s.indexPath())
312		if err != nil {
313			return index{}, err
314		}
315		var idx index
316		if err := json.Unmarshal(data, &idx); err != nil {
317			return index{}, err
318		}
319		if idx.Entries == nil {
320			idx.Entries = map[string]Entry{}
321		}
322		return idx, nil
323	}
324	
325	func (s *Store) save(idx index) error {
326		data, err := json.MarshalIndent(idx, "", "  ")
327		if err != nil {
328			return err
329		}
330		data = append(data, '\n')
331		tmp, err := os.CreateTemp(s.root, ".index-*")
332		if err != nil {
333			return err
334		}
335		tmpName := tmp.Name()
336		defer os.Remove(tmpName)
337		if _, err := tmp.Write(data); err != nil {
338			tmp.Close()
339			return err
340		}
341		if err := tmp.Close(); err != nil {
342			return err
343		}
344		return os.Rename(tmpName, s.indexPath())
345	}
346	
347	func (s *Store) indexPath() string               { return filepath.Join(s.root, "index.json") }
348	func (s *Store) lockPath() string                { return filepath.Join(s.root, ".lock") }
349	func (s *Store) objectPath(digest string) string { return filepath.Join(s.root, "objects", digest) }
350	
351	func validateName(name string) error {
352		if strings.TrimSpace(name) == "" || filepath.IsAbs(name) || name == "." || name == ".." || strings.HasPrefix(name, "../") || strings.Contains(name, "\\") {
353			return errors.New("name must be a nonempty relative slash-separated path")
354		}
355		clean := filepath.Clean(name)
356		if clean != name || strings.HasPrefix(clean, "../") {
357			return errors.New("name must be normalized and remain within the vault namespace")
358		}
359		return nil
360	}
