		closeErr := tmp.Close()
		if copyErr != nil {
			return copyErr
		}
		if closeErr != nil {
			return closeErr
		}
		digest := hex.EncodeToString(hash.Sum(nil))
		if err := s.placeObject(name, digest, size, tmpName); err != nil {
			return err
		}
		idx, err := s.load()
		if err != nil {
			return err
		}
