403		}
404		if infos[0].Count != 1 && infos[0].Count != 2 {
405			t.Fatalf("snapshot count=%d is neither pre- nor post-put mapping", infos[0].Count)
406		}
407		// Restore must yield a consistent mapping containing base.txt.
408		if err := store.RestoreSnapshot("concurrent"); err != nil {
409			t.Fatal(err)
410		}
411		entries, err := store.List()
412		if err != nil {
413			t.Fatal(err)
414		}
415		if infos[0].Count != len(entries) {
416			t.Fatalf("restored %d entries, snapshot had %d", len(entries), infos[0].Count)
417		}
418		found := false
419		for _, entry := range entries {
420			if entry.Name == "base.txt" {
421				found = true
