445	// TestRestoreRejectsIncompleteOrMisnamedRecords exercises the rule that a
446	// restore only swaps in a complete record whose name matches the selected
447	// snapshot in full. A missing, null, or non-object entries field is never an
448	// empty mapping, a wrong name is never applied, and malformed JSON is a
449	// corrupt record rather than an empty snapshot. Every failure names the
450	// selected snapshot, states what is wrong, and leaves the current mapping,
451	// the snapshot record, and the objects untouched.
452	func TestRestoreRejectsIncompleteOrMisnamedRecords(t *testing.T) {
453		goodDigest := hex.EncodeToString(sha256.New().Sum(nil))
454		entry := func() string {
455			return `{"name":"a.txt","digest":"` + goodDigest + `","size":0,"createdAt":"2026-01-01T00:00:00Z"}`
456		}
457		cases := map[string]struct {
458			snapshotName string
459			record       string
460			wantInError  string
461		}{
462			"missing entries": {
463				snapshotName: "s",
464				record:       `{"name":"s"}`,
465				wantInError:  "missing its entries mapping",
466			},
467			"null entries": {
468				snapshotName: "s",
469				record:       `{"name":"s","entries":null}`,
470				wantInError:  "missing its entries mapping",
471			},
472			"body is null": {
473				snapshotName: "s",
474				record:       `null`,
475				wantInError:  "malformed record",
476			},
477			"body is empty object": {
478				snapshotName: "s",
479				record:       `{}`,
480				wantInError:  "missing snapshot name",
481			},
482			"entries is an array": {
483				snapshotName: "s",
484				record:       `{"name":"s","entries":[]}`,
485				wantInError:  "entries mapping is malformed",
486			},
487			"entries is a string": {
488				snapshotName: "s",
489				record:       `{"name":"s","entries":"none"}`,
490				wantInError:  "entries mapping is malformed",
491			},
492			"entries is a number": {
493				snapshotName: "s",
494				record:       `{"name":"s","entries":3}`,
495				wantInError:  "entries mapping is malformed",
496			},
497			"missing name": {
498				snapshotName: "s",
499				record:       `{"entries":{}}`,
500				wantInError:  "missing snapshot name",
501			},
502			"null name": {
503				snapshotName: "s",
504				record:       `{"name":null,"entries":{}}`,
505				wantInError:  "malformed record",
506			},
507			"other name": {
508				snapshotName: "s",
509				record:       `{"name":"other","entries":{}}`,
510				wantInError:  "does not match snapshot",
511			},
512			// Multi-level names must match in full: the leaf name alone is wrong.
513			"nested name recorded as leaf": {
514				snapshotName: "releases/stable",
515				record:       `{"name":"stable","entries":{}}`,
516				wantInError:  `recorded name "stable" does not match snapshot "releases/stable"`,
517			},
518			"nested name recorded elsewhere": {
519				snapshotName: "releases/stable",
520				record:       `{"name":"releases/canary","entries":{}}`,
521				wantInError:  "does not match snapshot",
522			},
523			"unknown field": {
524				snapshotName: "s",
525				record:       `{"name":"s","entries":{},"extra":1}`,
526				wantInError:  "malformed record",
527			},
528			"duplicate name field": {
529				snapshotName: "s",
530				record:       `{"name":"other","name":"s","entries":{}}`,
531				wantInError:  "malformed record",
532			},
533			"duplicate entries field": {
534				snapshotName: "s",
535				record:       `{"name":"s","entries":null,"entries":{}}`,
536				wantInError:  "malformed record",
537			},
538			"trailing content": {
539				snapshotName: "s",
540				record:       `{"name":"s","entries":{}} {}`,
541				wantInError:  "malformed record",
542			},
543			"top level array": {
544				snapshotName: "s",
545				record:       `[]`,
546				wantInError:  "malformed record",
547			},
548			"entry missing digest": {
549				snapshotName: "s",
550				record:       `{"name":"s","entries":{"a.txt":{"name":"a.txt","size":0,"createdAt":"2026-01-01T00:00:00Z"}}}`,
551				wantInError:  "want 64 lowercase hex characters",
552			},
553			"duplicate entry key": {
554				snapshotName: "s",
555				record:       `{"name":"s","entries":{"a":` + entry() + `,"a":` + entry() + `}}`,
556				wantInError:  "malformed record",
557			},
558		}
559		for label, tc := range cases {
560			t.Run(label, func(t *testing.T) {
561				root := filepath.Join(t.TempDir(), "vault")
562				store := New(root)
563				input := writeFile(t, "keep me")
564				keepEntry, err := store.Put("keep.txt", input)
565				if err != nil {
566					t.Fatal(err)
567				}
568				writeSnapshotRecord(t, root, tc.snapshotName, tc.record)
569				recordPath := filepath.Join(root, "snapshots", filepath.FromSlash(tc.snapshotName)+".json")
570				recordBefore, err := os.ReadFile(recordPath)
571				if err != nil {
572					t.Fatal(err)
573				}
574				indexBefore, err := os.ReadFile(filepath.Join(root, "index.json"))
575				if err != nil {
576					t.Fatal(err)
577				}
578	
579				err = store.RestoreSnapshot(tc.snapshotName)
580				if err == nil {
581					t.Fatal("expected restore to be rejected")
582				}
583				if !strings.Contains(err.Error(), fmt.Sprintf("%q", tc.snapshotName)) {
584					t.Fatalf("error %q does not name the selected snapshot %q", err, tc.snapshotName)
585				}
586				if !strings.Contains(err.Error(), tc.wantInError) {
587					t.Fatalf("error %q does not indicate %q", err, tc.wantInError)
588				}
589	
590				// The current mapping survives intact and is still usable.
591				entries, err := store.List()
592				if err != nil {
593					t.Fatal(err)
594				}
595				if len(entries) != 1 || entries[0].Name != "keep.txt" || entries[0].Digest != keepEntry.Digest {
596					t.Fatalf("entries after failed restore=%+v", entries)
597				}
598				indexAfter, err := os.ReadFile(filepath.Join(root, "index.json"))
599				if err != nil {
600					t.Fatal(err)
601				}
602				if !reflect.DeepEqual(indexBefore, indexAfter) {
603					t.Fatalf("index changed on failed restore\nwas: %s\nnow: %s", indexBefore, indexAfter)
604				}
605				// The snapshot record is not rewritten or repaired.
606				recordAfter, err := os.ReadFile(recordPath)
607				if err != nil {
608					t.Fatal(err)
609				}
610				if !reflect.DeepEqual(recordBefore, recordAfter) {
611					t.Fatalf("snapshot record changed on failed restore\nwas: %s\nnow: %s", recordBefore, recordAfter)
612				}
613			})
614		}
615	}
