694	// TestRestoreMatchesRecordedMetadata verifies that a successful restore makes
695	// the current mapping byte-for-byte the snapshot's mapping: names, digests,
696	// sizes, and creation times all come from the record, and subsequent
697	// downloads fetch the snapshot's content.
698	func TestRestoreMatchesRecordedMetadata(t *testing.T) {
699		root := filepath.Join(t.TempDir(), "vault")
700		store := New(root)
701		v1 := writeFile(t, "version one\n")
702		v2 := writeFile(t, "version two\n")
703		old, err := store.Put("releases/app.txt", v1)
704		if err != nil {
705			t.Fatal(err)
706		}
707		if _, err := store.CreateSnapshot("snap"); err != nil {
708			t.Fatal(err)
709		}
710		if _, err := store.Put("releases/app.txt", v2); err != nil {
711			t.Fatal(err)
712		}
713		if err := store.RestoreSnapshot("snap"); err != nil {
714			t.Fatal(err)
715		}
716	
717		recordData, err := os.ReadFile(filepath.Join(root, "snapshots", "snap.json"))
718		if err != nil {
719			t.Fatal(err)
720		}
721		var recorded Snapshot
722		if err := json.Unmarshal(recordData, &recorded); err != nil {
723			t.Fatal(err)
724		}
725		indexData, err := os.ReadFile(filepath.Join(root, "index.json"))
726		if err != nil {
727			t.Fatal(err)
728		}
729		var current struct {
730			Entries map[string]Entry `json:"entries"`
731		}
732		if err := json.Unmarshal(indexData, &current); err != nil {
733			t.Fatal(err)
734		}
735		if !reflect.DeepEqual(recorded.Entries, current.Entries) {
736			t.Fatalf("restored mapping %+v != snapshot entries %+v", current.Entries, recorded.Entries)
737		}
738		if current.Entries["releases/app.txt"].Digest != old.Digest {
739			t.Fatal("restored entry does not point at the snapshot's object")
740		}
741	
742		out := filepath.Join(t.TempDir(), "app.txt")
743		if err := store.Get("releases/app.txt", out); err != nil {
744			t.Fatal(err)
745		}
746		got, err := os.ReadFile(out)
747		if err != nil {
748			t.Fatal(err)
749		}
750		if string(got) != "version one\n" {
751			t.Fatalf("download after restore=%q", got)
752		}
753	}
