// rules at the command line as the Go API: a successful create prints no
// success line (the snapshot shows up in `snapshot list`), while an unusable
// current mapping fails with an error naming the snapshot and the index,
// prints nothing, and leaves no snapshot behind.
func TestSnapshotCreateCLISilentOnSuccessRejectingCorruptIndex(t *testing.T) {
	root := filepath.Join(t.TempDir(), "vault")
	input := filepath.Join(t.TempDir(), "a.txt")
	if err := os.WriteFile(input, []byte("payload"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := run([]string{"init", "--root", root}); err != nil {
		t.Fatal(err)
	}
	if err := run([]string{"put", "--root", root, "--name", "a.txt", "--file", input}); err != nil {
		t.Fatal(err)
	}

	out := captureStdout(t, func() {
		if err := run([]string{"snapshot", "create", "--root", root, "--name", "good"}); err != nil {
			t.Fatal(err)
		}
	})
	if out != "" {
