	if err := os.WriteFile(filepath.Join(root, "index.json"),
		[]byte(`{"entries":null}`), 0o644); err != nil {
		t.Fatal(err)
	}
	var createErr error
	out = captureStdout(t, func() {
		createErr = run([]string{"snapshot", "create", "--root", root, "--name", "bad"})
